private static int GetCardValue(string card)
{
    int value = 0;
    string[] values = card.Split(" ");
    if (values[0] == "Ace")
    {
        value = 11;
    }
    else if (values[0] == "King" || values[0] == "Queen" || values[0] == "Jack")
    {
        value = 10;
    }
    else
    {
        value = int.Parse(values[0]);
    }
    return value;
}

```
