private static int GetHandValue(string[] cards)
{
    int value = 0;
    int aceCount = 0;
    foreach (string card in cards)
    {
        int cardValue = GetCardValue(card);
        if (cardValue == 11)
        {
            aceCount++;
        }
        value += cardValue;
    }

    while (value > 21 && aceCount > 0)
    {
        value -= 10;
        aceCount--;
    }

    return value;
}

